<?php
require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/db.php'; requireRole(['student']);
$id=(int)currentUser()['id']; $s=db()->prepare('SELECT u.username,u.email,p.student_number,p.phone,p.course,p.year_of_study,p.emergency_contact FROM users u LEFT JOIN student_profiles p ON p.user_id=u.id WHERE u.id=?'); $s->bind_param('i',$id); $s->execute(); $profile=$s->get_result()->fetch_assoc(); $s->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><title>My profile | CourtIQ</title><link rel="stylesheet" href="<?= projectUrl('assets/css/style.css') ?>"></head><body class="dashboard-layout"><main class="dashboard-content-main container"><a href="index.php" class="btn btn-secondary btn-sm">← Dashboard</a><section class="visual-card"><h1>Edit student profile</h1><?php if(!empty($_GET['success'])):?><p class="vcard-status">Profile saved.</p><?php endif; ?><form method="post" action="actions.php" class="admin-form"><?= csrfField() ?><input type="hidden" name="action" value="profile_save"><input name="email" type="email" required value="<?= e($profile['email']) ?>" placeholder="Email"><input name="student_number" maxlength="50" value="<?= e($profile['student_number']) ?>" placeholder="Student number"><input name="phone" maxlength="30" value="<?= e($profile['phone']) ?>" placeholder="Phone"><input name="course" maxlength="150" value="<?= e($profile['course']) ?>" placeholder="Course"><input name="year_of_study" type="number" min="1" max="20" value="<?= e($profile['year_of_study']) ?>" placeholder="Year"><input name="emergency_contact" maxlength="180" value="<?= e($profile['emergency_contact']) ?>" placeholder="Emergency contact"><button class="btn btn-primary">Save profile</button></form></section></main></body></html>
